'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const n = Number(input[0]);
const s = input[1];
const m = s.length;

const pi = Array(m).fill(0);
for (let i = 1; i < m; i++) {
    let j = pi[i - 1];
    while (j > 0 && s[i] !== s[j]) j = pi[j - 1];
    if (s[i] === s[j]) j++;
    pi[i] = j;
}

const matrix = Array.from({ length: m }, () => Array(m).fill(0n));

for (let state = 0; state < m; state++) {
    for (const bit of ['0', '1']) {
        let next = state;
        while (next > 0 && s[next] !== bit) next = pi[next - 1];
        if (s[next] === bit) next++;
        if (next < m) matrix[state][next]++;
    }
}

function multiply(a, b) {
    const size = a.length;
    const result = Array.from({ length: size }, () => Array(size).fill(0n));

    for (let i = 0; i < size; i++) {
        for (let k = 0; k < size; k++) {
            if (a[i][k] === 0n) continue;
            for (let j = 0; j < size; j++) {
                if (b[k][j] !== 0n) {
                    result[i][j] += a[i][k] * b[k][j];
                }
            }
        }
    }
    return result;
}

function matrixPower(base, exponent) {
    const size = base.length;
    let result = Array.from({ length: size }, (_, i) =>
        Array.from({ length: size }, (_, j) => i === j ? 1n : 0n)
    );

    while (exponent > 0) {
        if (exponent % 2 === 1) result = multiply(result, base);
        exponent = Math.floor(exponent / 2);
        if (exponent > 0) base = multiply(base, base);
    }
    return result;
}

const powered = matrixPower(matrix, n);
let avoiding = 0n;
for (let i = 0; i < m; i++) avoiding += powered[i][i];

const answer = (1n << BigInt(n)) - avoiding;
console.log(answer.toString());

